def skill(robot):
    if robot.is_holding():
        robot.put_aside()
    for _ in range(4):
        if robot.pick("purple cube"):
            if robot.place_on("tray"):
                return True
            if robot.place_on("green tray"):
                return True
            if robot.is_holding():
                robot.put_aside()
            return False
        blocker = robot.ask("Which object is on top of the purple cube?")
        if blocker:
            b = blocker.strip().lower()
            if "purple" not in b and "none" not in b and "nothing" not in b and "no " not in b:
                if robot.pick(b):
                    robot.put_aside()
                    continue
                if robot.pick(blocker):
                    robot.put_aside()
                    continue
        # fallback: try common blocking cubes
        cleared = False
        for color in ["red cube", "blue cube", "yellow cube", "green cube", "orange cube"]:
            if robot.pick(color):
                robot.put_aside()
                cleared = True
                break
        if not cleared:
            return False
    return False
